import forgelib as F
G = F.make(slug="the-forge-goblin-lord-quest", order=10, kw="goblin lord quest",
 title="The Forge Goblin Lord Quest: Unlock the Goblin's Crown",
 h1="The Forge Goblin Lord Quest: How to Unlock the Goblin's Crown Recipe",
 desc="The Forge Goblin Lord quest on Island 3: all four steps with gold and ore costs, the Goblin's Crown recipe it unlocks, its stats, and whether it's worth doing.",
 kw2=["the forge goblin quest island 3","the forge goblin crown","the forge goblin lord","the forge crown recipe","the forge frostspire quests"],
 related=["the-forge-goblin-cave","the-forge-armor-guide","the-forge-island-3-guide","the-forge-forging-guide"],
 ids=["C-mgWhS2Vr8","ZC18Zhrpb7w"],
 lead="The <strong>Goblin Lord quest</strong> is the Island 3 follow-up to the Goblin King's quests. Finish it and you unlock new forging recipes, including the <strong>Goblin's Crown</strong>. Fridge has a full walkthrough and a Short. Here are the exact costs from the Forge Wiki.",
 heading="Watch Fridge's Goblin Quest Videos",
 sections=[
 ("where","Where to Find the Goblin Lord","""<p>The Goblin Lord is a quest giver on the <strong>Frostspire Expanse</strong>, Island 3. You need to be level 70 or higher to travel there. Save plenty of Gold before you talk to him: every step costs more than the last.</p>"""),
 ("steps","Every Goblin Lord Quest Step","""<div class="table-wrap"><table><caption>Goblin Lord's quests (Forge Wiki, November 11, 2026)</caption><thead><tr><th scope="col">Quest</th><th scope="col">Bring</th><th scope="col">Reward (XP)</th></tr></thead><tbody>
<tr><td>Goblin Lord 1</td><td>25,000 Gold</td><td>1,000</td></tr>
<tr><td>Goblin Lord 2</td><td>1 Velchire + 50,000 Gold</td><td>1,500</td></tr>
<tr><td>Goblin Lord 3</td><td>2 Sanctis + 75,000 Gold</td><td>2,500</td></tr>
<tr><td>Goblin Lord 4</td><td>3 Snowite + 150,000 Gold</td><td>4,500</td></tr>
<tr><td>Let's get over it!</td><td>Final step</td><td>Recipe unlock</td></tr></tbody></table></div>
<p>The first four steps cost <strong>300,000 Gold</strong> in total, plus the ores. Velchire, Sanctis and Snowite are all Legendary Frostspire ores. Velchire can also be crafted from 1 Aetherit and 1 Lightite, and Snowite from 1 Blue Crystal Ore, 2 Diamond and 3 Sapphire at the Crafting Stall.</p>"""),
 ("crown","The Goblin's Crown Recipe","""<p>The <strong>Goblin's Crown</strong> is a heavy helmet and one of the few recipes you unlock through a quest. Its requirements are <strong>level 75</strong> plus finishing these quests. You can forge it on the Frostspire Expanse and Crimson Sakura.</p>
<ul><li><strong>Health:</strong> +26%, with a movement speed debuff.</li><li><strong>Chance:</strong> 1 in 6 within heavy helmets.</li><li><strong>Ores:</strong> 20 minimum, 26 recommended for the best odds, 35 to Lock Forge it.</li><li><strong>Base price:</strong> 1,020 Gold.</li></ul>
<p>For comparison, the Raven's Helmet gives +26.5% and the Shogun Helmet +34%. Compare every piece in our <a href="the-forge-armor-guide.html">armor guide</a>.</p>"""),
 ("worth","Is It Worth It?","""<p>Mostly for collectors. The Forge Wiki's Island 3 quest priority list marks these quests as <strong>very low priority</strong> and says the Goblin's Crown \"offers no real benefits\" over other helmets. Spend your first 300,000 Gold on Sensei Moro's and Bjorn's questlines, then the Raven questline. Come back when you have spare money. The Island 1 version is in our <a href="the-forge-goblin-cave.html">Goblin Cave guide</a>.</p>""")],
 faq=[("How much does the Goblin Lord quest cost in The Forge?","300,000 Gold across four steps, plus 1 Velchire, 2 Sanctis and 3 Snowite."),
      ("What do the Goblin Lord's quests unlock?","New forging recipes, including the Goblin's Crown heavy helmet, which also needs level 75."),
      ("Is the Goblin's Crown good?","It gives +26% Health, but the Forge Wiki rates it low priority because other helmets match or beat it.")],
 sources=[F.wiki("Goblin_Lord%27s_Questline","Goblin Lord's Questline"),F.wiki("Goblin_Lord_1","Goblin Lord 1–4 quests"),F.wiki("Goblin%27s_Crown","Goblin's Crown"),F.wiki("Crafting"),F.wiki("Guide","Community guide: quest priority")])
